function detectLocale(): Locale {
  if (typeof navigator === 'undefined') return 'en'
  return resolveLocale(navigator.languages?.[0] || navigator.language)
}

export function resolveLocale(languageTag: string | null | undefined): Locale {
  const language = String(languageTag || '').split(',')[0].trim().split('-')[0].toLowerCase() as Locale
  return TRANSLATIONS[language] ? language : 'en'
}

/** Direction is centralized even though the current language set is LTR, so
 * adding Arabic/Hebrew/Persian/Urdu does not require page-level rewrites. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  return /^(ar|fa|he|ur)(-|$)/i.test(locale) ? 'rtl' : 'ltr'
}

export function translate(locale: Locale, key: string, params?: Record<string, string | number>): string {
  const dictionary = TRANSLATIONS[locale] || TRANSLATIONS.en
  let resolvedKey = key
  if (params && Number.isFinite(Number(params.count))) {
    const category = new Intl.PluralRules(locale).select(Number(params.count))
    if (dictionary[`${key}_${category}`] || TRANSLATIONS.en[`${key}_${category}`]) resolvedKey = `${key}_${category}`
    else if (dictionary[`${key}_other`] || TRANSLATIONS.en[`${key}_other`]) resolvedKey = `${key}_other`
  }
  let str = dictionary[resolvedKey] || TRANSLATIONS.en[resolvedKey] || resolvedKey
  if (params) for (const [param, value] of Object.entries(params)) str = str.split(`{${param}}`).join(String(value))
  return str
}

// Browser locale never changes within a session, so subscribing is a no-op;
// useSyncExternalStore still gives us a hydration-safe server snapshot ('en')
// that React reconciles with the real client locale after mount.
const emptySubscribe = () => () => {}

export function useLocale(): Locale {
  return useSyncExternalStore(emptySubscribe, detectLocale, () => 'en')
}

export function useTranslations() {
  const locale = useLocale()

  return function t(key: string, params?: Record<string, string | number>): string {
    return translate(locale, key, params)
  }
}
